// fixed precision regardless of radius
async function nearby(lat, lng, radiusKm) {
  const cell = geohash.encode(lat, lng, 7);   // ~150 m cells, always
  const cells = [cell, ...geohash.neighbors(cell)];   // 3x3 grid
  const rows = [];
  for (const c of cells) {
    rows.push(...await db.byPrefix(c));       // gather candidates
  }
  // sort by geohash string distance as a proxy for real distance
  rows.sort((a, b) =>
    a.geohash < b.geohash ? -1 : a.geohash > b.geohash ? 1 : 0);
  return rows;
}
